{
      "id": "ml02-linear-classification",
      "title": "Linear classifiers, discriminants, and logistic models",
      "kind": "A",
      "category": "machine-learning",
      "label": "ML-13",
      "companion": "ml02-linear-classification-examples",
      "requires": [
        "convex-and-semicontinuous-functions-on-rn",
        "inner-product-spaces-and-orthogonality",
        "the-spectral-theorem-and-singular-value-decomposition",
        "generalized-linear-models-and-fisher-scoring",
        "mixed-effects-and-longitudinal-models"
