          ]
        },
        {
          "id": "lem-indicator-response-least-squares-minimum-norm-fit",
          "kind": "lemma",
          "title": "The minimum-norm indicator-response least-squares fit exists uniquely",
          "deps": [
            "def-indicator-response-least-squares-classifier",
            "thm-least-squares-solutions-and-normal-equation",
            "thm-singular-value-decomposition"
          ],
          "statement": "Let $n,q\\ge1$ and $K\\ge2$ be finite, let $X\\in\\mathbb R^{n\\times q}$, and let $Y\\in\\mathbb R^{n\\times K}$ be an indicator response matrix. Among all minimizers of $\\|Y-XB\\|_F^2$ over $B\\in\\mathbb R^{q\\times K}$ there is a unique one of smallest Frobenius norm. If $X=U_rD_rV_r^T$ is a thin singular-value decomposition with rank $r>0$, orthonormal columns in $U_r,V_r$, and positive diagonal entries in $D_r$, then this minimizer is $B_*=V_rD_r^{-1}U_r^TY$. If $r=0$, then $X=0$ and $B_*=0$. In either case the full minimizer set is $\\{B_*+N:XN=0\\}$.",
          "strategy": "Use SVD to construct the projection fit, then the least-squares normal equation and row-space/kernel orthogonality to prove the unique minimum-norm property.",
          "proof_strategy": "direct",
          "sources": {
            "references": [
              {
                "title": "Hastie, Tibshirani, and Friedman, The Elements of Statistical Learning, 2nd ed., corrected 12th printing",
                "url": "https://drive.google.com/uc?export=download&id=1--Wo5Hcl2y_v3DL-tGgcJHRPdtjiVYjS"
              }
            ]
