        },
        {
          "id": "alg-cyclic-perceptron",
          "kind": "algorithm",
          "title": "The cyclic perceptron update procedure",
          "deps": [],
          "statement": "Input a finite ordered sample $((x_i,y_i))_{i=1}^n$ with $n\\ge1$, $x_i\\in\\mathbb R^d$, and $y_i\\in\\{-1,+1\\}$. Put $\\widetilde x_i=(x_i,1)\\in\\mathbb R^{d+1}$ and initialize $w=0$. In each pass, visit $i=1,\\ldots,n$ in the fixed order. Whenever $y_iw^T\\widetilde x_i\\le0$, replace $w$ by $w+y_i\\widetilde x_i$ and count one update. After a full pass with no updates, stop and return $w$. The associated classifier returns $+1$ when $w^T(x,1)>0$ and $-1$ when $w^T(x,1)\\le0$, so a score tie is assigned to $-1$. The procedure has no iteration limit; if its stop condition never holds, it continues with further passes.",
          "strategy": "Specify the finite ordered sample, augmented bias coordinate, zero initialization, exact non-strict update and full-pass stop rule without a convergence claim.",
          "sources": {
            "references": [
              {
                "title": "Hastie, Tibshirani, and Friedman, The Elements of Statistical Learning, 2nd ed., corrected 12th printing",
                "url": "https://drive.google.com/uc?export=download&id=1--Wo5Hcl2y_v3DL-tGgcJHRPdtjiVYjS"
              },
              {
                "title": "Stanford CS229 Spring 2022 lecture notes",
                "url": "https://cs229.stanford.edu/lectures-spring2022/main_notes.pdf"
              }
            ]
          },
          "provenance": {
            "statement": "literature-derived",
            "proof": "not-applicable"
          },
          "dependency_level": 0,
          "justified_by": []
        },
        {
          "id": "thm-perceptron-margin-mistake-bound",
          "kind": "theorem",
          "title": "The perceptron makes at most R squared over gamma squared mistakes",
          "deps": [
            "alg-cyclic-perceptron",
            "thm-cauchy-schwarz-for-real-and-complex-inner-product-spaces"
          ],
          "statement": "Let $((x_i,y_i))_{i=1}^n$ be a finite ordered sample with $n\\ge1$, $x_i\\in\\mathbb R^d$, and $y_i\\in\\{-1,+1\\}$. Put $\\widetilde x_i=(x_i,1)\\in\\mathbb R^{d+1}$, with Euclidean inner product $\\langle u,v\\rangle=u^Tv$ and norm $\\|u\\|_2=(u^Tu)^{1/2}$. Suppose $\\|\\widetilde x_i\\|_2\\le R$ for every $i$ and there is a unit vector $u\\in\\mathbb R^{d+1}$ and $\\gamma>0$ such that $y_i\\langle u,\\widetilde x_i\\rangle\\ge\\gamma$ for every $i$. The zero-initialized cyclic procedure that visits the sample in the stated order and updates $w\\leftarrow w+y_i\\widetilde x_i$ whenever $y_i\\langle w,\\widetilde x_i\\rangle\\le0$ makes at most $R^2/\\gamma^2$ updates and stops after a finite pass with no updates. At each visit, before its update, the procedure predicts $+1$ if $\\langle w,\\widetilde x_i\\rangle>0$ and $-1$ otherwise; a prediction mistake is a visit on which this prediction differs from $y_i$. The total number of such mistakes before termination is at most $R^2/\\gamma^2$. The returned weight vector has strictly positive signed margin on every sample point.",
          "strategy": "Accumulate separator progress and bound squared norm at each update, combine the inequalities by Cauchy–Schwarz, and deduce finite termination.",
          "proof_strategy": "direct",
          "sources": {
