      "items": [
        {
          "id": "ex-knn-symmetrization-changes-ratio-cut",
          "kind": "example",
          "title": "KNN symmetrization changes a graph cut",
          "statement": "Take $x_1=0$, $x_2=1$, and $x_3=3$ on $\\mathbb R$, and let each point choose its unique nearest neighbor ($k=1$). Define the union graph to contain a unit-weight edge when either directed nearest-neighbor choice selects it, and the mutual graph to contain a unit-weight edge only when both directions select it. For the partition $\\{1,2\\},\\{3\\}$, the RatioCut is $3/2$ on the union graph and $0$ on the mutual graph.",
          "deps": [
            "def-finite-weighted-graph-laplacian",
            "def-ratio-cut-and-normalized-cut"
          ],
          "justified_by": [],
          "dependency_level": 2,
          "strategy": "Compute the directed nearest-neighbor choices, construct both symmetric supports, then evaluate the two cut terms for the fixed partition.",
          "sources": {
            "references": [
              {
                "title": "Ulrike von Luxburg, A Tutorial on Spectral Clustering, Statistics and Computing 17(4), 2007",
                "url": "https://cs.brown.edu/courses/csci1820/spring-2022/resources/vonLuxburg_2007.pdf"
              },
              {
                "title": "Jean Gallier, Notes on Elementary Spectral Graph Theory: Applications to Graph Clustering Using Normalized Cuts, 2013",
                "url": "https://arxiv.org/pdf/1311.2492"
              }
            ]
          }
        },
        {
          "id": "ex-disconnected-weighted-components-spectral-clustering",
          "kind": "example",
          "title": "Disconnected weighted components are zero-cut clusters",
          "statement": "Let $V=\\{1,2,3,4\\}$ and set $w_{12}=w_{21}=2$, $w_{34}=w_{43}=3$, with every other entry zero. For the algorithm inputs, take $n=4$, $p=1$, $x_i=i\\in\\mathbb R$ for $1\\le i\\le4$, and the constant deterministic graph builder $G:(\\mathbb R^1)^4\\to\\mathbb R^{4\\times4}$ defined by $G(y_1,y_2,y_3,y_4)=W=(w_{ij})$ for every input tuple. Use mode $\\texttt{ratio}$ and $k=2$. The partition $\\{1,2\\},\\{3,4\\}$ has RatioCut and Ncut equal to $0$, and deterministic unnormalized spectral clustering with $k=2$ returns these two components under the specified eigenspace and farthest-first tie rules.",
          "deps": [
            "def-finite-weighted-graph-laplacian",
            "def-ratio-cut-and-normalized-cut",
            "lem-weighted-graph-laplacian-quadratic-form-and-kernel",
            "alg-weighted-spectral-clustering"
          ],
          "justified_by": [],
          "dependency_level": 5,
          "strategy": "Compute degrees, cuts, volumes, and the two zero modes; verify the prescribed embedding has exactly two distinct rows and Lloyd returns their partition.",
          "sources": {
            "references": [
              {
                "title": "Ulrike von Luxburg, A Tutorial on Spectral Clustering, Statistics and Computing 17(4), 2007",
                "url": "https://cs.brown.edu/courses/csci1820/spring-2022/resources/vonLuxburg_2007.pdf"
              },
              {
                "title": "Jean Gallier, Notes on Elementary Spectral Graph Theory: Applications to Graph Clustering Using Normalized Cuts, 2013",
                "url": "https://arxiv.org/pdf/1311.2492"
              }
            ]
          }
        },
        {
          "id": "ex-isolated-vertex-in-normalized-cut",
          "kind": "example",
          "title": "An isolate is excluded from Ncut and reinserted separately",
          "statement": "Let $V=\\{1,2,3\\}$ with $w_{12}=w_{21}=1$ and every other weight zero. For the algorithm inputs, take $n=3$, $p=1$, $x_i=i\\in\\mathbb R$ for $1\\le i\\le3$, and the constant deterministic graph builder $G:(\\mathbb R^1)^3\\to\\mathbb R^{3\\times3}$ defined by $G(y_1,y_2,y_3)=W=(w_{ij})$ for every input tuple. In mode $\\texttt{normalized}$ with $k=1$ and row normalization disabled (the default), the positive-degree vertex set is $V_+=\\{1,2\\}$, the active Ncut cluster is $\\{1,2\\}$ with value $0$, and vertex $3$ is returned separately as the singleton $\\{3\\}$ without entering any Ncut denominator.",
