      "id": "ml02-latent-representations",
      "title": "Latent factors, ICA, NMF, and representation ambiguity",
      "kind": "A",
      "category": "machine-learning",
      "label": "ML-22",
      "companion": "ml02-latent-representations-examples",
      "requires": [
        "the-spectral-theorem-and-singular-value-decomposition",
        "characteristic-functions-inversion-and-continuity",
        "improper-and-parameter-dependent-multiple-integrals",
        "measures-and-their-basic-properties",
