{
      "id": "ml02-differential-privacy",
      "title": "Differential privacy mechanisms and composition",
      "kind": "A",
      "category": "machine-learning",
      "label": "ML-27",
      "companion": "ml02-differential-privacy-examples",
      "requires": [
        "conditional-distributions-and-regular-conditional-probability",
        "measures-and-their-basic-properties",
        "probability-spaces-random-variables-and-expectation",
        "sigma-algebras-and-borel-sets",
