        {
          "id": "ex-finite-mdp-common-reward-shift",
          "kind": "example",
          "title": "A common reward shift moves every one-state Bellman value equally",
          "deps": [
            "def-finite-markov-decision-process",
            "def-policy-bellman-operator",
            "def-bellman-optimality-operator",
            "thm-bellman-contraction-and-unique-fixed-point"
          ],
          "dependency_level": 3,
          "statement": "Let $S=\\{s\\}$, $A(s)=\\{a,b\\}$, and $\\gamma=1/2$. Both actions return deterministically to $s$, with reward $1$ under $a$ and reward $3$ under $b$. View the deterministic policies choosing $a$ and $b$ as stationary policies assigning probability one to those actions; their unique policy Bellman fixed points are $2$ and $6$, respectively. More generally, for a stationary policy with $\\theta:=\\pi(b\\mid s)\\in[0,1]$, its fixed point is $2+4\\theta$. After adding $2$ to both rewards, the deterministic-policy fixed points are $6$ and $10$, and the fixed point for the same stochastic policy is $6+4\\theta$. Thus every policy value shifts by $2/(1-\\gamma)=4$, the difference between the two deterministic-policy values remains $4$, and $b$ maximizes the Bellman optimality backup at the optimal fixed point in both models.",
          "strategy": "Evaluate the two geometric discounted returns before and after the common reward shift.",
          "proof_strategy": "direct",
          "sources": {
            "references": [
              {
                "title": "Richard S. Sutton and Andrew G. Barto, Reinforcement Learning: An Introduction, 2nd ed.",
                "url": "https://web.stanford.edu/class/psych209/Readings/SuttonBartoIPRLBook2ndEd.pdf",
