        {
          "id": "alg-pomdp-witness-backup",
          "kind": "algorithm",
          "title": "Exhaustive finite-horizon POMDP alpha-vector backup",
          "deps": [
            "def-finite-pomdp",
            "def-sum-over-a-finite-index-set"
