        {
          "id": "lem-finite-pomdp-belief-update-is-probability-kernel",
          "kind": "lemma",
          "title": "The finite POMDP Bayes filter is a probability kernel",
          "deps": [
            "def-finite-pomdp",
            "def-belief-state-and-bayes-filter",
            "def-measure-kernel-and-probability-kernel",
